import { describe, test, expect } from "bun:test"
import { z } from "zod"

import type {
  AnthropicStreamEventData,
  AnthropicStreamState,
} from "~/routes/messages/anthropic-types"
import type {
  ChatCompletionChunk,
  ChatCompletionResponse,
} from "~/services/copilot/create-chat-completions"

import { translateToAnthropic } from "~/routes/messages/non-stream-translation"
import { translateChunkToAnthropicEvents } from "~/routes/messages/stream-translation"
import {
  createResponsesStreamState,
  translateResponsesStreamEvent,
} from "~/services/copilot/create-responses"

const anthropicUsageSchema = z.object({
  input_tokens: z.number().int(),
  output_tokens: z.number().int(),
})

const anthropicContentBlockTextSchema = z.object({
  type: z.literal("text"),
  text: z.string(),
})

const anthropicContentBlockToolUseSchema = z.object({
  type: z.literal("tool_use"),
  id: z.string(),
  name: z.string(),
  input: z.record(z.string(), z.any()),
})

const anthropicMessageResponseSchema = z.object({
  id: z.string(),
  type: z.literal("message"),
  role: z.literal("assistant"),
  content: z.array(
    z.union([
      anthropicContentBlockTextSchema,
      anthropicContentBlockToolUseSchema,
    ]),
  ),
  model: z.string(),
  stop_reason: z.enum(["end_turn", "max_tokens", "stop_sequence", "tool_use"]),
  stop_sequence: z.string().nullable(),
  usage: anthropicUsageSchema,
})

/**
 * Validates if a response payload conforms to the Anthropic Message shape.
 * @param payload The response payload to validate.
 * @returns True if the payload is valid, false otherwise.
 */
function isValidAnthropicResponse(payload: unknown): boolean {
  return anthropicMessageResponseSchema.safeParse(payload).success
}

const anthropicStreamEventSchema = z.looseObject({
  type: z.enum([
    "message_start",
    "content_block_start",
    "content_block_delta",
    "content_block_stop",
    "message_delta",
    "message_stop",
  ]),
})

function isValidAnthropicStreamEvent(payload: unknown): boolean {
  return anthropicStreamEventSchema.safeParse(payload).success
}

type AnthropicToolStartEvent = Extract<
  AnthropicStreamEventData,
  { type: "content_block_start" }
> & {
  content_block: { type: "tool_use"; id: string; name: string }
}

type AnthropicInputJsonDeltaEvent = Extract<
  AnthropicStreamEventData,
  { type: "content_block_delta" }
> & {
  delta: { type: "input_json_delta"; partial_json: string }
}

type AnthropicMessageDeltaEvent = Extract<
  AnthropicStreamEventData,
  { type: "message_delta" }
>

type AnthropicMessageStartEvent = Extract<
  AnthropicStreamEventData,
  { type: "message_start" }
>

function collectToolStreamDetails(events: Array<AnthropicStreamEventData>) {
  const messageStarts: Array<AnthropicMessageStartEvent> = []
  const toolStarts: Array<AnthropicToolStartEvent> = []
  const inputJsonDeltas: Array<AnthropicInputJsonDeltaEvent> = []
  const messageDeltas: Array<AnthropicMessageDeltaEvent> = []
  let messageStops = 0

  for (const event of events) {
    if (event.type === "message_start") {
      messageStarts.push(event)
    }

    if (
      event.type === "content_block_start"
      && event.content_block.type === "tool_use"
    ) {
      toolStarts.push(event as AnthropicToolStartEvent)
    }

    if (
      event.type === "content_block_delta"
      && event.delta.type === "input_json_delta"
    ) {
      inputJsonDeltas.push(event as AnthropicInputJsonDeltaEvent)
    }

    if (event.type === "message_delta") {
      messageDeltas.push(event)
    }

    if (event.type === "message_stop") {
      messageStops++
    }
  }

  return {
    messageStarts,
    toolStarts,
    inputJsonDeltas,
    messageDeltas,
    messageStops,
  }
}

