describe("pricing updater recovery", () => {
  it("retains successful timestamps on failure and clears errors on recovery", async () => {
    const directory = await fs.mkdtemp(path.join(os.tmpdir(), "pricing-test-"))
    const target = path.join(directory, "pricing.json")
    try {
      const first = await updateCopilotPricing(
        Object.assign(
          () =>
            Promise.resolve(
              new Response(fixture, { headers: { etag: '"first"' } }),
            ),
          { preconnect: () => {} },
        ),
        target,
      )
      const fetchedAt = first.cache?.source.fetched_at
      const validatedAt = first.cache?.source.validated_at

      const failed = await updateCopilotPricing(
        Object.assign(() => Promise.reject(new Error("offline")), {
          preconnect: () => {},
        }),
        target,
      )
      expect(failed.status).toBe("stale")
      expect(failed.cache?.source.fetched_at).toBe(fetchedAt)
      expect(failed.cache?.source.validated_at).toBe(validatedAt)
      expect(failed.cache?.source.last_attempt_at).toBeDefined()
      expect(failed.cache?.source.error).toBe("offline")

      const recovered = await updateCopilotPricing(
        Object.assign(
          (_input: string | URL | Request, init?: RequestInit) => {
            expect(new Headers(init?.headers).get("if-none-match")).toBe(
              '"first"',
            )
            return Promise.resolve(new Response(null, { status: 304 }))
          },
          { preconnect: () => {} },
        ),
        target,
      )
      expect(recovered.status).toBe("not-modified")
      expect(recovered.cache?.source.stale).toBe(false)
      expect(recovered.cache?.source.error).toBeUndefined()
      expect(recovered.cache?.source.validated_at).not.toBe(validatedAt)
      expect(await readCopilotPricing(target)).toEqual(recovered.cache)
    } finally {
      await fs.rm(directory, { recursive: true, force: true })
    }
  })
})

import { describe, expect, spyOn, test } from "bun:test"
import consola from "consola"

import type { AnthropicStreamState } from "~/routes/messages/anthropic-types"

import { translateChunkToAnthropicEvents } from "~/routes/messages/stream-translation"
import {
  createResponsesStreamState,
  translateResponsesStreamEvent,
} from "~/services/copilot/create-responses"

function newAnthropicState(): AnthropicStreamState {
  return {
    messageStartSent: false,
    contentBlockIndex: 0,
    contentBlockOpen: false,
    toolCalls: {},
  }
}

function runStream(
  events: Array<{ event: string; data: Record<string, unknown> }>,
) {
  const state = createResponsesStreamState()
  const chunks = events.flatMap((event) =>
    Array.from(translateResponsesStreamEvent(event, state)),
  )
  return { state, chunks }
}

const toolCallAdded = (callId = "call_x", name = "echo") => ({
  event: "response.output_item.added",
  data: {
    item: {
      type: "function_call",
      call_id: callId,
      id: "item-1",
      name,
      arguments: "",
    },
    output_index: 0,
  },
})

const argsDelta = (delta: string) => ({
  event: "response.function_call_arguments.delta",
  data: { delta, output_index: 0 },
})

const argsDone = (args: string) => ({
  event: "response.function_call_arguments.done",
  data: { arguments: args, output_index: 0 },
})

describe("syncToolArguments divergence guard", () => {
  test("identity: done equals accumulated -> zero extra chunks, no warn", () => {
    const warnSpy = spyOn(consola, "warn").mockImplementation(
      Object.assign(() => {}, { raw: () => {} }),
    )
    try {
      const { chunks } = runStream([
        toolCallAdded(),
        argsDelta('{"x":"hel'),
        argsDelta('lo"}'),
        argsDone('{"x":"hello"}'),
      ])
      const argDeltaChunks = chunks.filter(
        (c) => c.choices[0]?.delta?.tool_calls?.[0]?.function?.arguments,
      )
      // 2 from explicit deltas, 0 from done (identity).
      expect(argDeltaChunks).toHaveLength(2)
      expect(warnSpy).not.toHaveBeenCalled()
    } finally {
      warnSpy.mockRestore()
    }
  })

  test("extension: done extends accumulated -> exactly one suffix chunk, no warn", () => {
    const warnSpy = spyOn(consola, "warn").mockImplementation(
      Object.assign(() => {}, { raw: () => {} }),
    )
    try {
      const { chunks } = runStream([
        toolCallAdded(),
        argsDelta('{"x":"hel'),
        argsDone('{"x":"hello"}'),
      ])
      const argDeltaChunks = chunks.filter(
        (c) => c.choices[0]?.delta?.tool_calls?.[0]?.function?.arguments,
      )
      // 1 from delta + 1 from done suffix.
      expect(argDeltaChunks).toHaveLength(2)
      const suffix =
        argDeltaChunks[1]?.choices[0]?.delta?.tool_calls?.[0]?.function
          ?.arguments
      expect(suffix).toBe('lo"}')
      expect(warnSpy).not.toHaveBeenCalled()
    } finally {
      warnSpy.mockRestore()
    }
  })

  test("divergence: done disagrees with accumulated -> zero extra chunks, warn invoked, accumulator preserved", () => {
    const warnSpy = spyOn(consola, "warn").mockImplementation(
      Object.assign(() => {}, { raw: () => {} }),
    )
    try {
      const { chunks } = runStream([
        toolCallAdded(),
        argsDelta('{"x":"hello"}'),
        argsDone('{"y":"world"}'),
      ])
      const argDeltaChunks = chunks.filter(
        (c) => c.choices[0]?.delta?.tool_calls?.[0]?.function?.arguments,
      )
      // 1 from delta only; done is suppressed.
      expect(argDeltaChunks).toHaveLength(1)
      expect(warnSpy).toHaveBeenCalledTimes(1)
      const call = warnSpy.mock.calls[0] as
        | [string, Record<string, unknown>]
        | undefined
      const payload = call?.[1]
      expect(payload).toMatchObject({
        callId: "call_x",
        name: "echo",
        accumulatedLength: '{"x":"hello"}'.length,
        candidateLength: '{"y":"world"}'.length,
      })
    } finally {
      warnSpy.mockRestore()
    }
  })

  test("end-to-end on divergence: reassembled tool_use input is the streamed prefix and parses", () => {
    const warnSpy = spyOn(consola, "warn").mockImplementation(
      Object.assign(() => {}, { raw: () => {} }),
    )
    try {
      const { chunks } = runStream([
        toolCallAdded(),
        argsDelta('{"x":"hello"}'),
        argsDone('{"y":"world"}'),
      ])
      const anthropicState = newAnthropicState()
      const events = chunks.flatMap((c) =>
        translateChunkToAnthropicEvents(c, anthropicState),
      )
      const partialJson = events
        .filter((e) => e.type === "content_block_delta")
        .map((e) => e as { delta?: { type?: string; partial_json?: string } })
        .filter((e) => e.delta?.type === "input_json_delta")
        .map((e) => e.delta?.partial_json ?? "")
        .join("")
      expect(partialJson).toBe('{"x":"hello"}')
      expect(JSON.parse(partialJson)).toEqual({ x: "hello" })
    } finally {
      warnSpy.mockRestore()
    }
  })
})

import { describe, expect, spyOn, test } from "bun:test"
import consola from "consola"

import type { AnthropicStreamState } from "~/routes/messages/anthropic-types"

import { translateChunkToAnthropicEvents } from "~/routes/messages/stream-translation"
import {
  createResponsesStreamState,
  translateResponsesStreamEvent,
} from "~/services/copilot/create-responses"

function newAnthropicState(): AnthropicStreamState {
  return {
    messageStartSent: false,
    contentBlockIndex: 0,
    contentBlockOpen: false,
    toolCalls: {},
  }
}

function runStream(
  events: Array<{ event: string; data: Record<string, unknown> }>,
) {
  const state = createResponsesStreamState()
  const chunks = events.flatMap((event) =>
    Array.from(translateResponsesStreamEvent(event, state)),
  )
  return { state, chunks }
}

function translateChunks(chunks: ReturnType<typeof runStream>["chunks"]) {
  const anthropicState = newAnthropicState()
  return chunks.flatMap((chunk) =>
    translateChunkToAnthropicEvents(chunk, anthropicState),
  )
}

const created = (id = "resp-1", model = "gpt-test") => ({
  event: "response.created",
  data: { response: { id, model } },
})

const textDelta = (delta: string) => ({
  event: "response.output_text.delta",
  data: { delta, output_index: 0 },
})

describe("Responses streaming terminal-error events", () => {
  test("response.failed yields one chunk with error and emits Anthropic error event", () => {
    const warnSpy = spyOn(consola, "warn").mockImplementation(
      Object.assign(() => {}, { raw: () => {} }),
    )
    try {
      const { chunks } = runStream([
        created(),
        textDelta("hi"),
        {
          event: "response.failed",
          data: {
            response: {
              id: "resp-1",
              error: {
                type: "rate_limit_exceeded",
                message: "too many requests",
              },
            },
          },
        },
      ])

      const errorChunks = chunks.filter((c) => c.error)
      expect(errorChunks).toHaveLength(1)
      expect(errorChunks[0]?.error).toEqual({
        type: "rate_limit_exceeded",
        message: "too many requests",
      })
      expect(errorChunks[0]?.choices[0]?.finish_reason).toBeNull()

      const events = translateChunks(chunks)
      const errorEvents = events.filter((e) => e.type === "error")
      expect(errorEvents).toHaveLength(1)
      expect(events.at(-1)?.type).toBe("error")
      const last = errorEvents[0] as {
        error: { type: string; message: string }
      }
      expect(last.error).toEqual({
        type: "rate_limit_exceeded",
        message: "too many requests",
      })
      expect(events.some((e) => e.type === "message_stop")).toBe(false)
      expect(events.some((e) => e.type === "content_block_stop")).toBe(true)
      expect(warnSpy).toHaveBeenCalledTimes(1)
    } finally {
      warnSpy.mockRestore()
    }
  })

  test("generic error event yields chunk with error and emits Anthropic error event", () => {
    const warnSpy = spyOn(consola, "warn").mockImplementation(
      Object.assign(() => {}, { raw: () => {} }),
    )
    try {
      const { chunks } = runStream([
        created(),
        {
          event: "error",
          data: { code: "internal_error", message: "boom" },
        },
      ])

      const errorChunks = chunks.filter((c) => c.error)
      expect(errorChunks).toHaveLength(1)
      expect(errorChunks[0]?.error?.type).toBe("internal_error")
      expect(errorChunks[0]?.error?.message).toBe("boom")

      const events = translateChunks(chunks)
      const errorEvents = events.filter((e) => e.type === "error")
      expect(errorEvents).toHaveLength(1)
      const last = errorEvents[0] as {
        error: { type: string; message: string }
      }
      expect(last.error.type).toBe("internal_error")
      expect(last.error.message).toBe("boom")
      expect(events.some((e) => e.type === "message_stop")).toBe(false)
      expect(warnSpy).toHaveBeenCalledTimes(1)
    } finally {
      warnSpy.mockRestore()
    }
  })

  test("response.incomplete with max_output_tokens maps to length and emits message_stop", () => {
    const warnSpy = spyOn(consola, "warn").mockImplementation(
      Object.assign(() => {}, { raw: () => {} }),
    )
    try {
      const { chunks } = runStream([
        created(),
        textDelta("hi"),
        {
          event: "response.incomplete",
          data: {
            response: {
              id: "resp-1",
              incomplete_details: { reason: "max_output_tokens" },
            },
          },
        },
      ])

      const terminal = chunks.at(-1)
      expect(terminal?.choices[0]?.finish_reason).toBe("length")
      expect(terminal?.error).toBeUndefined()

      const events = translateChunks(chunks)
      expect(events.some((e) => e.type === "message_stop")).toBe(true)
      expect(events.some((e) => e.type === "error")).toBe(false)
      const md = events.find((e) => e.type === "message_delta") as
        | { delta: { stop_reason: string | null } }
        | undefined
      expect(md?.delta.stop_reason).toBe("max_tokens")
      expect(warnSpy).not.toHaveBeenCalled()
    } finally {
      warnSpy.mockRestore()
    }
  })

  test("response.incomplete with no reason maps to stop", () => {
    const warnSpy = spyOn(consola, "warn").mockImplementation(
      Object.assign(() => {}, { raw: () => {} }),
    )
    try {
      const { chunks } = runStream([
        created(),
        textDelta("hi"),
        {
          event: "response.incomplete",
          data: {
            response: {
              id: "resp-1",
              incomplete_details: {},
            },
          },
        },
      ])

      const terminal = chunks.at(-1)
      expect(terminal?.choices[0]?.finish_reason).toBe("stop")
      expect(warnSpy).not.toHaveBeenCalled()
    } finally {
      warnSpy.mockRestore()
    }
  })
})
